CREATE TABLE dissentOverTimeData(
   id              VARCHAR(5) NOT NULL PRIMARY KEY
  ,party           VARCHAR(19) NOT NULL
  ,vote_id         VARCHAR(6) NOT NULL
  ,procedure_type  VARCHAR(3) NOT NULL
  ,timestamp       VARCHAR(23) NOT NULL
  ,num_for         VARCHAR(3) NOT NULL
  ,num_against     VARCHAR(3) NOT NULL
  ,num_abstention  VARCHAR(3) NOT NULL
  ,num_no_votes    VARCHAR(3) NOT NULL
  ,total_votes     VARCHAR(3) NOT NULL
  ,majority_col    VARCHAR(10) NOT NULL
  ,majority_votes  VARCHAR(3) NOT NULL
  ,percent_dissent VARCHAR(18) NOT NULL
  ,year            VARCHAR(4) NOT NULL
  ,month           VARCHAR(2) NOT NULL
  ,weekday         VARCHAR(1) NOT NULL
  ,weekofyear      VARCHAR(2) NOT NULL
  ,adjusted_week   VARCHAR(3) NOT NULL
);
